public List<int> Fibonacci(int n)
{
    var result = new List<int>();

    if (n <= 0)
        return result;

    result.Add(0);
    if (n == 1)
        return result;

    result.Add(1);

    while (result.Count < n)
        result.Add(result[^1] + result[^2]);

    return result;
}

