using NUnit.Framework;
using System.Collections.Generic;

[TestFixture]
public class FibonacciTests
{
    [Test]
    public void Fibonacci_Returns_First_Seven()
    {
        var result = Fibonacci(7);
        Assert.That(result, Is.EqualTo(new List<int> { 0, 1, 1, 2, 3, 5, 8 }));
    }

    private List<int> Fibonacci(int n)
    {
        var result = new List<int>();

        if (n <= 0)
            return result;

        result.Add(0);
        if (n == 1)
            return result;

        result.Add(1);

        while (result.Count < n)
            result.Add(result[^1] + result[^2]);

        return result;
    }
}
